const RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/;
function bad(s){ return !s || typeof s !== "string" || !RE.test(s); }
const i = $input.first().json;
if (bad(i.namespace) || bad(i.pod)) return [{json: {blocked: true, ok: false, detail: "invalid or missing namespace/pod"}}];
// container is optional; the model may send "", "null" or "undefined" for "not set".
let container = typeof i.container === "string" ? i.container.trim() : "";
if (["", "null", "undefined", "none"].includes(container.toLowerCase())) container = "";
if (container && bad(container)) return [{json: {blocked: true, ok: false, detail: "invalid container name"}}];
let base = `https://kubernetes.default.svc/api/v1/namespaces/${i.namespace}/pods/${i.pod}/log?tailLines=200`;
if (String(i.previous) === "true") base += "&previous=true";
const url = container ? `${base}&container=${container}` : base;
const podUrl = `https://kubernetes.default.svc/api/v1/namespaces/${i.namespace}/pods/${i.pod}`;
return [{json: {url, base, podUrl, container}}];

// A pod with several containers makes the log API answer 400
// "a container name must be specified for pod X, choose one of: [...]".
// When no container was requested, look the pod up and retry with its main
// container. The list in the error message is not used for the choice: it
// puts init containers first.
const r = $input.first().json;
const prep = $('Prepare').first().json;
if (prep.blocked) return [{json: {blocked: true, detail: prep.detail, retry: false}}];
const body = String(r.body ?? r.data ?? "");
const ambiguous = r.statusCode === 400 && !prep.container && body.includes("a container name must be specified");
if (!ambiguous) return [{json: {...r, retry: false, container: prep.container || ""}}];
return [{json: {retry: true, url: prep.podUrl}}];

// Main container = the kubectl default-container annotation when it names a
// real container, otherwise the first regular (non-init) container.
const RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/;
const r = $input.first().json;
const prep = $('Prepare').first().json;
let pod = null;
try { pod = JSON.parse(String(r.body ?? r.data ?? "")); } catch (e) {}
const containers = (pod?.spec?.containers ?? []).map(c => c.name).filter(c => RE.test(c));
if (r.statusCode >= 400 || !containers.length) {
  // Keep url empty of a container: the log call then repeats the original 400,
  // which Result reports as it is.
  return [{json: {url: prep.base, container: "", containers}}];
}
const init = (pod.spec.initContainers ?? []).map(c => c.name).filter(c => RE.test(c));
const preferred = pod.metadata?.annotations?.["kubectl.kubernetes.io/default-container"];
const container = containers.includes(preferred) ? preferred : containers[0];
return [{json: {url: `${prep.base}&container=${container}`, container, containers, init}}];

const r = $input.first().json;
const check = $('Check Response').first().json;
if (check.blocked) return [{json: {ok: false, detail: check.detail}}];
const extra = {};
if (check.retry) {
  const c = $('Choose Container').first().json;
  if (c.container) {
    extra.container = c.container;
    const others = c.containers.filter(n => n !== c.container).concat(c.init);
    extra.note = `pod has several containers; showing "${c.container}". Pass container to read another one: ${others.join(", ")}.`;
  }
} else if (check.container) {
  extra.container = check.container;
}
if (r.statusCode >= 400) return [{json: {ok: false, detail: `K8s API ${r.statusCode}: ${String(r.body ?? r.data).slice(0,300)}`, ...extra}}];
let log = String(r.body ?? r.data ?? "");
if (log.length > 6000) log = "...(truncated)...\n" + log.slice(-6000);
return [{json: {ok: true, log, ...extra}}];
